function getSelected(p){if(!s.selected)return null;const k=s.selected.type,id=s.selected.id;let result=k==='evidence'?p.evidence.find(x=>x.evidence_id===id):k==='topic'?p.topics.find(x=>x.id===id):k==='requirement'?p.requirements.find(x=>x.id===id):k==='issue'?p.issues.find(x=>x.id===id):k==='question'?p.questions.find(x=>x.id===id):null;return result?{kind:k,item:result}:null}
